from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 14.1 The Solar System · 7ESs.01, 7ESs.02
# =====================================================================================================
READ["14.1"] = L(
    H("Lights in the evening sky",
      "Just after sunset, a very bright 'star' often appears low in the west. It does not twinkle like the others.",
      "It is actually the planet Venus. How can a planet shine if it does not make its own light?"),
    I("Our Solar System",
      "The **Solar System** is the Sun and everything that orbits it: eight planets, their moons, dwarf planets, asteroids and comets. ('Sol' is Latin for Sun.)",
      fig={"kind": "orbits"},
      table=[["Group", "Planets", "Made of"], ["inner planets", "Mercury, Venus, Earth, Mars", "mainly rock – small and dense"],
             ["outer planets (gas giants)", "Jupiter, Saturn, Uranus, Neptune", "mainly gases such as hydrogen and helium – huge"]],
      then=["Between Mars and Jupiter lies the **asteroid belt**: countless rocks, from pebbles to hundreds of kilometres across."]),
    I("Stars, planets and orbits",
      "The **Sun is a star**: a huge ball of extremely hot, glowing gas that gives out its own light. Stars are round, not star-shaped.",
      then=["A **planet** is a large ball of rock or gas that orbits a star. Planets do **not** give out light – we see them because they **reflect sunlight**.",
            "Planets travel round the Sun in slightly stretched circles called **elliptical orbits**."]),
    I("Real data: how long is a year?",
      "A planet's **year** is the time it takes to orbit the Sun once.",
      fig={"kind": "barchart", "labels": ["Mercury", "Venus", "Earth", "Mars", "Jupiter"], "values": [88, 225, 365, 687, 4331], "ymax": 4500, "step": 500,
           "ylabel": "length of year (Earth days)", "xlabel": "planet"},
      then=["The further a planet is from the Sun, the **longer its year**: it has further to travel and it moves more slowly. Jupiter's year is almost 12 Earth years."]),
    Y("Read the chart",
      num("s7u14r11", "About how many Earth days longer is a year on Mars than a year on Earth?", 322, "Subtract Earth's year from Mars's year.", "687 − 365 = 322 days.",
          errs=[(1052, "Subtract, do not add.")])),
    I("What keeps planets in orbit?",
      "The Sun has more than 99% of all the mass in the Solar System, so its **gravity** is enormous.",
      then=["Each planet is moving fast sideways. The Sun's gravity pulls it inwards and bends its path into an orbit. Too slow and it would fall into the Sun; too fast and it would fly off into space."]),
    I("Moons, days, years and seasons",
      "A **moon** is a **natural satellite** that orbits a planet; satellites we launch are **artificial satellites**. All planets except Mercury and Venus have moons.",
      table=[["Time", "Caused by", "On Earth"], ["**day**", "the planet spinning once on its axis", "24 hours"], ["**year**", "the planet orbiting the Sun once", "365¼ days"]],
      then=["The Earth's axis is **tilted**. In June the northern half leans towards the Sun – longer days and summer in the north; in December it leans away – winter in the north and summer in the south."]),
    I("How stars and planets form",
      "Stars form in huge clouds of **dust and gas** in space. Gravity pulls the material together; it gets hotter and hotter until it starts to glow as a new star.",
      then=["Leftover dust and gas spinning round the young star clump together to form planets. Our Solar System formed this way about 4.6 billion years ago."]),
    Y("Star or planet?",
      grid("s7u14r12", "Is each one a star or a planet?", ["Star", "Planet"],
           [("gives out its own light", "Star"), ("orbits the Sun", "Planet"), ("the Sun", "Star"), ("shines by reflecting sunlight", "Planet"), ("Jupiter", "Planet")],
           "Which makes its own light?", "Stars give out light (the Sun); planets reflect it and orbit a star.")),
    K("Key points",
      "The **Solar System**: the Sun, 8 planets (4 rocky inner, 4 gas giants), moons, asteroids, comets.",
      "The Sun is a **star**; planets reflect its light and travel in **elliptical orbits**.",
      "Further from the Sun → longer year. Gravity keeps planets in orbit.",
      "Day = one spin; year = one orbit; seasons come from the tilt of the axis.",
      "Stars and planets form from clouds of dust and gas pulled together by gravity."),
    book=BK(
        [("Solar System", "the Sun and everything that orbits it"), ("star", "a huge ball of hot glowing gas that gives out light"), ("planet", "a large body that orbits a star"),
         ("orbit", "the path of an object round another"), ("moon", "a natural satellite of a planet"), ("asteroid belt", "the region of rocks between Mars and Jupiter")],
        [], [],
        [Ex("List the planets in order from the Sun.", ans="Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune"),
         Ex("Give two differences between the inner and outer planets.", ans="inner: small, rocky; outer: huge, made mainly of gas"),
         Ex("Explain why we can see planets even though they do not give out light.", ans="They reflect light from the Sun."),
         Ex("What causes (a) a day (b) a year (c) seasons on Earth?", ans="(a) the Earth spinning on its axis (b) the Earth orbiting the Sun (c) the tilt of the Earth's axis"),
         Ex("Saturn is further from the Sun than Jupiter. Predict whether its year is longer or shorter than Jupiter's. Explain.", ans="Longer – it is further away, so it travels further and more slowly.", think=True)],
        ["describe the Solar System", "explain the difference between stars and planets", "explain what keeps planets in orbit", "explain days, years and seasons",
         "describe how stars and planets form"],
        look=["inner and outer planets", "the length-of-year chart"],
        note="Read it after the video: the Solar System, orbits, days, years and seasons (answers at the back)."),
)

# =====================================================================================================
# 14.2 Gravity and tides · 7ESs.03
# =====================================================================================================
READ["14.2"] = L(
    H("The disappearing beach",
      "In the morning the beach is wide and sandy. By lunchtime the sea has covered it almost up to the trees. In the evening it is wide again.",
      "What makes the sea rise and fall twice a day?"),
    I("What causes tides?",
      "The **Moon's gravity** pulls on the Earth – including its oceans.",
      fig={"kind": "sciTides"},
      then=["The ocean facing the Moon bulges towards it. There is a second bulge on the opposite side, where the water is pulled least and the Earth's rotation swings it outwards.",
            "As the Earth spins once a day, each place passes through **both bulges**: **two high tides and two low tides** about every 24 hours 50 minutes."]),
    I("Real data: sea level at a harbour",
      "A tide gauge recorded the height of the sea over one day:",
      fig={"kind": "linegraph", "x": {"min": 0, "max": 24, "step": 3, "label": "time (hours after midnight)"}, "y": {"min": 0, "max": 5, "step": 1, "label": "sea level (m)"},
           "series": [{"pts": [[0, 2.0], [3, 3.9], [5, 4.4], [6, 4.2], [9, 2.0], [11, 0.8], [12, 0.6], [15, 2.3], [18, 4.2], [18.5, 4.3], [21, 2.6], [24, 0.9]]}]},
      then=["High tide at about 05:00 (4.4 m), low tide at about 12:00 (0.6 m), and high tide again about 12½ hours after the first. The difference between high and low tide is the **tidal range**."]),
    Y("Tidal range",
      num("s7u14r21", "Use the graph. What is the tidal range (high tide − low tide) on this day, in metres?", 3.8, "Subtract the lowest level from the highest.",
          "4.4 − 0.6 = 3.8 m.", errs=[(5, "Use the high and low tide readings, not the axis.")])),
    I("Spring tides and neap tides",
      "The **Sun's gravity** affects tides too, but less than the Moon's because the Sun is so much further away.",
      table=[["Tides", "Sun and Moon", "Effect", "When"],
             ["**spring tides**", "in a straight line with the Earth", "pulls add together: very high high tides and very low low tides (biggest range)", "twice a month: new moon and full moon"],
             ["**neap tides**", "at right angles to each other", "pulls partly cancel: smallest range", "twice a month: half moon"]],
      fig={"kind": "sciTides", "sun": "line"},
      then=["'Spring' here has nothing to do with the season – it means the water 'springs up'."]),
    I("Why tides matter",
      "Large ships can only enter some harbours at high tide, so every port publishes a **tide table**. Fishermen, surfers and lifeguards check it too.",
      then=["Very high spring tides plus storms and rising sea levels (from climate change) can flood coastal towns, so people need warnings in advance."]),
    Y("Spring or neap?",
      mcq("s7u14r22", "The Sun, Earth and Moon are in a straight line. What kind of tides happen?",
          [("spring tides – the biggest tidal range", True, "Yes – the pulls add together."), ("neap tides – the smallest range", False, "Neap tides happen when they are at right angles."),
           ("no tides", False, "There are always tides."), ("only one high tide a day", False, "There are still two high tides a day.")],
          "Do the pulls add or cancel?", "In line, the pulls of the Sun and Moon add together: spring tides.")),
    K("Key points",
      "The **Moon's gravity** pulls the oceans into two bulges: two high and two low tides a day.",
      "The **tidal range** is the difference between high and low tide.",
      "**Spring tides** (Sun and Moon in line): biggest range. **Neap tides** (at right angles): smallest range.",
      "Tide tables help shipping and flood warnings."),
    book=BK(
        [("tide", "the regular rise and fall of the sea"), ("tidal range", "the difference in height between high and low tide"),
         ("spring tide", "a tide with a very large range, when the Sun and Moon are in line"), ("neap tide", "a tide with a small range, when the Sun and Moon are at right angles")],
        [], [],
        [Ex("Explain why there are two high tides each day.", ans="The Moon's gravity makes two bulges of water on opposite sides of the Earth; the Earth spins through both each day."),
         Ex("Why does the Sun affect tides less than the Moon, even though it is much more massive?", ans="It is much further away, and gravity gets weaker with distance."),
         Ex("Describe the positions of the Sun, Moon and Earth for (a) spring tides (b) neap tides.", ans="(a) in a straight line (b) the Moon at right angles to the Sun"),
         Ex("A harbour's high tide is at 06:10. Estimate the time of the next high tide.", ans="about 18:35 (about 12 h 25 min later)", think=True)],
        ["explain how the Moon causes tides", "read a tide graph and find the tidal range", "explain spring and neap tides"],
        look=["the two bulges", "the harbour tide graph"],
        note="Read it after the video: tides, the tide graph and spring and neap tides (answers at the back)."),
)

