# 14.3 Eclipses · 7ESs.04
# =====================================================================================================
READ["14.3"] = L(
    H("Darkness at midday",
      "In a total solar eclipse, the sky goes dark in the middle of the day, birds stop singing and the temperature drops – for just a few minutes.",
      "What could block out the Sun? Make a prediction."),
    I("Shadows",
      "Light travels in **straight lines**. When an object blocks the light, a **shadow** forms behind it.",
      then=["A large light source like the Sun makes two parts of shadow: the **umbra**, where all the light is blocked (very dark), and the **penumbra**, where only part is blocked (partly dark)."]),
    I("Predict, watch, explain: modelling an eclipse",
      "A torch (the Sun), a small ball (the Moon) and a big ball (the Earth) are lined up in a dark room.",
      then=["When the small ball is exactly between the torch and the big ball, a small dark shadow falls on **one part** of the big ball; the rest stays lit.",
            "People in the darkest part would see a **total** eclipse; people nearby would see a **partial** eclipse. That is why a solar eclipse can be seen only from some places on Earth."]),
    I("Solar eclipse",
      "A **solar eclipse** happens when the **Moon passes between the Sun and the Earth** and casts its shadow on the Earth.",
      fig={"kind": "sciEclipse", "type": "solar"},
      then=["In the **umbra** you see a **total** eclipse; in the **penumbra** a **partial** eclipse. During a total eclipse scientists can study the Sun's faint outer atmosphere, the **corona**.",
            "**Never look directly at the Sun**, even during an eclipse – it can permanently damage your eyes. Use eclipse glasses or a pinhole viewer."]),
    I("Lunar eclipse",
      "A **lunar eclipse** happens when the **Earth is between the Sun and the Moon**, so the Moon moves into the Earth's shadow.",
      fig={"kind": "sciEclipse", "type": "lunar"},
      then=["The Moon often looks **red**: the Earth's atmosphere bends some sunlight onto the Moon and scatters away most of the blue light, leaving red. A lunar eclipse can be seen from anywhere it is night-time, and it is safe to watch."]),
    Y("Solar or lunar?",
      grid("s7u14r31", "Which kind of eclipse is described?", ["Solar eclipse", "Lunar eclipse"],
           [("the Moon is between the Sun and the Earth", "Solar eclipse"), ("the Moon turns a coppery red", "Lunar eclipse"), ("the Earth's shadow falls on the Moon", "Lunar eclipse"),
            ("the sky goes dark during the day", "Solar eclipse")],
           "Whose shadow falls on whom?", "Moon's shadow on Earth = solar; Earth's shadow on Moon = lunar.")),
    Y("Umbra or penumbra?",
      mcq("s7u14r32", "During a solar eclipse, Amir sees only part of the Sun covered. Where is he?",
          [("in the penumbra", True, "Yes – only part of the light is blocked there."), ("in the umbra", False, "In the umbra the Sun is completely covered."),
           ("on the Moon", False, "He is on Earth."), ("outside the shadow completely", False, "Then he would see no eclipse.")],
          "Partial or total?", "A partial eclipse is seen from the penumbra.")),
    K("Key points",
      "Light travels in straight lines; blocked light makes a shadow with an **umbra** (total) and a **penumbra** (partial).",
      "**Solar eclipse**: Moon between Sun and Earth; Moon's shadow on Earth. Never look at the Sun.",
      "**Lunar eclipse**: Earth between Sun and Moon; the Moon in Earth's shadow often looks red."),
    book=BK(
        [("eclipse", "when one object in space blocks light from another"), ("solar eclipse", "the Moon blocks the Sun's light from part of the Earth"),
         ("lunar eclipse", "the Moon passes into the Earth's shadow"), ("umbra", "the darkest part of a shadow"), ("penumbra", "the lighter, partial part of a shadow")],
        [], [],
        [Ex("Draw the positions of the Sun, Earth and Moon in (a) a solar eclipse (b) a lunar eclipse.", ans="(a) Sun – Moon – Earth in a line (b) Sun – Earth – Moon in a line"),
         Ex("Explain the difference between the umbra and the penumbra.", ans="All the light is blocked in the umbra (total darkness); only part is blocked in the penumbra."),
         Ex("Why does the Moon look red during a lunar eclipse?", ans="Earth's atmosphere bends some red sunlight onto the Moon, while most blue light is scattered away."),
         Ex("Why can a total solar eclipse be seen only from a narrow strip of the Earth?", ans="The Moon's umbra is small, so it covers only a small part of the Earth's surface at a time.", think=True)],
        ["explain how shadows form", "explain solar and lunar eclipses", "describe the umbra and penumbra"],
        look=["the solar eclipse diagram", "the lunar eclipse diagram"],
        note="Read it after the video: shadows, solar and lunar eclipses, umbra and penumbra (answers at the back)."),
)

