# 14.4 Developing models of space · 7SIC.01, 7TWSm.01
# =====================================================================================================
READ["14.4"] = L(
    H("Who moves?",
      "Every day the Sun rises in the east and sets in the west. It really looks as if the Sun goes round the Earth.",
      "What evidence could show that it is actually the Earth that moves?"),
    I("From Earth-centred to Sun-centred",
      "People's models of space have changed many times as new evidence appeared.",
      table=[["Who", "When", "Idea"],
             ["Chinese astronomers", "about 4000 years ago", "recorded eclipses and later predicted them"],
             ["Ptolemy", "about 150 CE, Egypt", "**geocentric** model: the Earth at the centre, everything orbits it"],
             ["Al-Sijzi; al-Tusi", "900s; 1261, Persia", "suggested the Earth rotates; listed problems with Ptolemy's model"],
             ["Nicolaus Copernicus", "1543, Poland", "**heliocentric** model: the Sun at the centre; the Earth spins and orbits the Sun"],
             ["Galileo Galilei", "1610, Italy", "telescope showed moons orbiting Jupiter and phases of Venus – evidence against the geocentric model"]],
      then=["Many people at first rejected the new model, choosing only evidence that suited their beliefs – an example of **bias**."]),
    I("Science keeps building",
      "Each new discovery built on earlier work.",
      table=[["Who", "Discovery"], ["Isaac Newton (1687)", "laws of gravity explain why planets orbit the Sun"], ["William and Caroline Herschel (1780s)", "found Uranus; catalogued comets, star clusters and nebulae"],
             ["Astronomers (1846)", "used Newton's laws to predict where an unknown planet should be – and found Neptune"],
             ["Edwin Hubble (1920s)", "showed there are other galaxies and the Universe is expanding"],
             ["Jocelyn Bell Burnell (1967)", "discovered pulsars – spinning remains of stars that send out radio pulses"],
             ["Stephen Hawking (1970s)", "showed black holes should give out radiation"]],
      then=["Old ideas are **replaced or improved** when new evidence comes along. That is how science works."]),
    Y("Which model?",
      mcq("s7u14r41", "Why did seeing moons orbiting Jupiter not fit the geocentric model?",
          [("It showed that not everything orbits the Earth.", True, "Yes – here were objects orbiting another planet."), ("It proved the Earth is flat.", False, "It says nothing about the shape of the Earth."),
           ("It showed Jupiter orbits the Moon.", False, "The moons orbit Jupiter."), ("It showed the Sun orbits Jupiter.", False, "No.")],
          "In the geocentric model, what does everything orbit?", "The geocentric model said everything orbits the Earth; Jupiter's moons orbit Jupiter.")),
    I("Real life: testing models of space today",
      "Scientists still test their models with new evidence.",
      fig=CARD("Tools of modern astronomy", [{"icon": "satellite", "t": "Space telescopes", "d": "above the air: see very distant galaxies clearly"},
                                             {"icon": "planet", "t": "Space probes", "d": "fly to planets and moons and send back data"},
                                             {"icon": "ear", "t": "Radio telescopes", "d": "detect radio waves from space"},
                                             {"icon": "globe", "t": "Earth satellites", "d": "measure the Sun, Moon and Earth"}], 4)),
    Y("Put in order",
      mcq("s7u14r42", "Which list is in the right time order?",
          [("Ptolemy, Copernicus, Galileo, Newton", True, "Yes."), ("Copernicus, Ptolemy, Newton, Galileo", False, "Ptolemy came first, about 1400 years before Copernicus."),
           ("Galileo, Copernicus, Ptolemy, Newton", False, "Ptolemy was the earliest."), ("Newton, Galileo, Copernicus, Ptolemy", False, "That is backwards.")],
          "Use the tables.", "Ptolemy (150 CE), Copernicus (1543), Galileo (1610), Newton (1687).")),
    K("Key points",
      "**Geocentric** model (Ptolemy): Earth at the centre. **Heliocentric** model (Copernicus): Sun at the centre.",
      "Galileo's telescope evidence (Jupiter's moons, phases of Venus) supported the heliocentric model.",
      "Newton, the Herschels, Hubble, Bell Burnell and Hawking each built on earlier work.",
      "Models change when new evidence appears; bias can slow down acceptance of new ideas."),
    book=BK(
        [("geocentric model", "a model with the Earth at the centre of the Universe"), ("heliocentric model", "a model with the Sun at the centre of the Solar System"),
         ("galaxy", "a huge group of billions of stars"), ("bias", "choosing only the evidence that suits your opinion")],
        [], [],
        [Ex("Describe the difference between the geocentric and heliocentric models.", ans="Geocentric: Earth at the centre with everything orbiting it; heliocentric: Sun at the centre with the planets, including Earth, orbiting it."),
         Ex("Give two pieces of evidence Galileo found for the heliocentric model.", ans="moons orbiting Jupiter; the phases of Venus"),
         Ex("How was Neptune discovered?", ans="Scientists used Newton's laws to predict where it should be, then found it."),
         Ex("Quick quiz.", ("What keeps the planets in orbit?", "the Sun's gravity (balanced by their speed)"), ("What causes spring tides?", "the Sun and Moon in line"),
            ("Where is the Moon in a solar eclipse?", "between the Sun and the Earth"), ("Who proposed a Sun-centred model in 1543?", "Copernicus")),
         Ex("Explain why the Sun appears to rise and set if it is the Earth that moves.", ans="The Earth spins on its axis, so from the ground the Sun appears to move across the sky.", think=True)],
        ["describe how models of the Solar System developed", "explain why models change with new evidence", "give examples of modern tools that test our models"],
        look=["the timeline tables", "evidence for the heliocentric model"],
        note="Read it after the video: geocentric and heliocentric models, the scientists who changed our ideas and a quick quiz (answers at the back)."),
)
